  s11_2 = c("xbar <- ...", "mu0 <- ...  # claimed mean", "sigma <- ...", "n <- ...", "alpha <- ..."),
  s11_3 = c("xbar <- ...", "mu0 <- ...  # claimed mean", "s <- ...", "n <- ...", "alpha <- ..."),
  s11_5 = c("x <- ...  # successes", "n <- ...", "p0 <- ...  # claimed proportion", "alpha <- ..."),
  s11_6 = c("n <- ...", "s <- ...", "sigma0 <- ...  # claimed SD", "alpha <- ..."),
  s12_1 = c("xbar1/xbar2 <- ...  # sample means", "sigma1/sigma2 <- ...  # known population SDs", "n1/n2 <- ..."),
  s12_2 = c("xbar1/xbar2 <- ...", "s1/s2 <- ...  # sample SDs", "n1/n2 <- ..."),
  s12_3 = c("before <- c(...)", "after <- c(...)", "d <- before - after"),
